-- Stable IDs are UUID strings generated by the application layer.
CREATE TABLE programme (
  id TEXT PRIMARY KEY NOT NULL,
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT ''
);

CREATE TABLE domain (
  id TEXT PRIMARY KEY NOT NULL,
  programme_id TEXT NOT NULL REFERENCES programme(id),
  name TEXT NOT NULL,
  UNIQUE (programme_id, name)
);

CREATE TABLE site (
  id TEXT PRIMARY KEY NOT NULL,
  programme_id TEXT NOT NULL REFERENCES programme(id),
  name TEXT NOT NULL,
  site_type TEXT NOT NULL DEFAULT 'Unknown'
);

CREATE TABLE branch_pattern (
  id TEXT PRIMARY KEY NOT NULL,
  programme_id TEXT NOT NULL REFERENCES programme(id),
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT ''
);

CREATE TABLE branch (
  id TEXT PRIMARY KEY NOT NULL,
  site_id TEXT NOT NULL UNIQUE REFERENCES site(id),
  branch_pattern_id TEXT REFERENCES branch_pattern(id),
  branch_code TEXT
);

CREATE TABLE device (
  id TEXT PRIMARY KEY NOT NULL,
  site_id TEXT NOT NULL REFERENCES site(id),
  domain_id TEXT REFERENCES domain(id),
  name TEXT NOT NULL,
  device_role TEXT NOT NULL DEFAULT 'Unknown',
  vendor TEXT
);

CREATE TABLE interface (
  id TEXT PRIMARY KEY NOT NULL,
  device_id TEXT NOT NULL REFERENCES device(id),
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  UNIQUE (device_id, name)
);

CREATE TABLE circuit (
  id TEXT PRIMARY KEY NOT NULL,
  site_id TEXT NOT NULL REFERENCES site(id),
  name TEXT NOT NULL,
  provider TEXT,
  circuit_type TEXT NOT NULL DEFAULT 'Unknown'
);

CREATE TABLE vlan (
  id TEXT PRIMARY KEY NOT NULL,
  site_id TEXT NOT NULL REFERENCES site(id),
  vlan_number INTEGER NOT NULL CHECK (vlan_number BETWEEN 1 AND 4094),
  name TEXT,
  UNIQUE (site_id, vlan_number)
);

CREATE TABLE vrf (
  id TEXT PRIMARY KEY NOT NULL,
  programme_id TEXT NOT NULL REFERENCES programme(id),
  name TEXT NOT NULL,
  UNIQUE (programme_id, name)
);

CREATE TABLE sdwan_vpn (
  id TEXT PRIMARY KEY NOT NULL,
  programme_id TEXT NOT NULL REFERENCES programme(id),
  vpn_number INTEGER NOT NULL CHECK (vpn_number >= 0),
  name TEXT,
  UNIQUE (programme_id, vpn_number)
);

CREATE TABLE subnet (
  id TEXT PRIMARY KEY NOT NULL,
  site_id TEXT REFERENCES site(id),
  vrf_id TEXT REFERENCES vrf(id),
  cidr TEXT NOT NULL,
  purpose TEXT NOT NULL DEFAULT ''
);

CREATE TABLE routing_adjacency (
  id TEXT PRIMARY KEY NOT NULL,
  device_a_id TEXT NOT NULL REFERENCES device(id),
  device_b_id TEXT NOT NULL REFERENCES device(id),
  protocol TEXT NOT NULL,
  CHECK (device_a_id <> device_b_id)
);

CREATE TABLE service (
  id TEXT PRIMARY KEY NOT NULL,
  programme_id TEXT NOT NULL REFERENCES programme(id),
  domain_id TEXT REFERENCES domain(id),
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT ''
);

CREATE TABLE architecture_decision (
  id TEXT PRIMARY KEY NOT NULL,
  programme_id TEXT NOT NULL REFERENCES programme(id),
  title TEXT NOT NULL,
  rationale TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'Proposed',
  decided_at TEXT
);

CREATE TABLE dependency (
  id TEXT PRIMARY KEY NOT NULL,
  from_service_id TEXT NOT NULL REFERENCES service(id),
  to_service_id TEXT NOT NULL REFERENCES service(id),
  description TEXT NOT NULL DEFAULT '',
  CHECK (from_service_id <> to_service_id),
  UNIQUE (from_service_id, to_service_id)
);

CREATE TABLE source_document (
  id TEXT PRIMARY KEY NOT NULL,
  programme_id TEXT NOT NULL REFERENCES programme(id),
  title TEXT NOT NULL,
  source_type TEXT NOT NULL,
  relative_path TEXT,
  captured_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- A fact has one explicit time horizon and one explicit information perspective.
-- subject_kind/subject_id are resolved by the application when facts are created.
CREATE TABLE architecture_fact (
  id TEXT PRIMARY KEY NOT NULL,
  programme_id TEXT NOT NULL REFERENCES programme(id),
  subject_kind TEXT NOT NULL,
  subject_id TEXT NOT NULL,
  fact_key TEXT NOT NULL,
  fact_value TEXT NOT NULL,
  time_horizon TEXT NOT NULL CHECK (time_horizon IN ('Current State','Transition State','Future State')),
  perspective TEXT NOT NULL CHECK (perspective IN ('Design Intent','Observed State','Validated State','As-Built State')),
  classification TEXT NOT NULL DEFAULT 'Unknown' CHECK (classification IN ('Unknown','Observed','Client Confirmed','Architect Confirmed','Inferred','Target','As-Built')),
  recorded_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE evidence (
  id TEXT PRIMARY KEY NOT NULL,
  fact_id TEXT NOT NULL REFERENCES architecture_fact(id),
  source_document_id TEXT REFERENCES source_document(id),
  evidence_type TEXT NOT NULL,
  note TEXT NOT NULL DEFAULT '',
  captured_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE validation_rule (
  id TEXT PRIMARY KEY NOT NULL,
  programme_id TEXT NOT NULL REFERENCES programme(id),
  name TEXT NOT NULL,
  rule_code TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  UNIQUE (programme_id, rule_code)
);

CREATE TABLE validation_result (
  id TEXT PRIMARY KEY NOT NULL,
  validation_rule_id TEXT NOT NULL REFERENCES validation_rule(id),
  fact_id TEXT NOT NULL REFERENCES architecture_fact(id),
  outcome TEXT NOT NULL CHECK (outcome IN ('Pass','Fail','Unknown')),
  note TEXT NOT NULL DEFAULT '',
  checked_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE INDEX idx_domain_programme ON domain(programme_id);
CREATE INDEX idx_site_programme ON site(programme_id);
CREATE INDEX idx_device_site ON device(site_id);
CREATE INDEX idx_fact_subject ON architecture_fact(subject_kind, subject_id);
CREATE INDEX idx_fact_programme ON architecture_fact(programme_id);
CREATE INDEX idx_evidence_fact ON evidence(fact_id);
CREATE INDEX idx_validation_fact ON validation_result(fact_id);
